css:
/* ═══════════ 栖迟 QICHI ═══════════
   基底：暖纸米白 + 常春藤墨绿 + 炭棕 + 砂岩琥珀
   模度：4/8px 阶梯 · 光源：右上 135° · 色温：全栈暖调
*/

:root{
  --paper:#F4EFE6;          /* 60% Canvas */
  --paper-deep:#EAE1D2;
  --panel:#FBF7EF;
  --ink:#173300;            /* 主文字 */
  --ink-2:#3A4A2C;          /* 次要文字 */
  --ink-muted:#5E6B4F;      /* 说明文字 */
  --brown:#3A322A;          /* 炭棕 · 结构 */
  --line:#D3C9B6;
  --line-soft:#E2D9C7;
  --accent:#A9611F;         /* 砂岩琥珀 · 交互可读档 */
  --accent-warm:#E9B473;    /* 插画暖光 */
  --shadow-lift:0 18px 36px -18px rgba(23,51,0,.18),0 4px 10px -6px rgba(23,51,0,.08);

  --f-sans:"PingFang SC","Hiragino Sans GB","Source Han Sans SC","Noto Sans SC","Microsoft YaHei",system-ui,sans-serif;
  --f-serif:"Songti SC","Source Han Serif SC","Noto Serif SC",Georgia,"Times New Roman",serif;
  --f-mono:ui-monospace,"SFMono-Regular",Menlo,Consolas,monospace;
  --ease:cubic-bezier(.16,1,.3,1);
}

*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth}
body{
  margin:0;
  background:var(--paper);
  color:var(--ink);
  font-family:var(--f-sans);
  font-size:16px;
  line-height:1.65;
  -webkit-font-smoothing:antialiased;
  overflow-x:hidden;
}
h1,h2,h3,h4{margin:0}
p{margin:0}
img,svg{display:block;max-width:100%}
a{color:inherit}

/* 纸感颗粒：固定层，低位 z-index，不参与滚动重绘 */
.grain-layer{
  position:fixed;inset:0;pointer-events:none;z-index:0;isolation:isolate;opacity:.3;
  background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='140' height='140'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='3'/><feColorMatrix type='saturate' values='0'/></filter><rect width='140' height='140' filter='url(%23n)' opacity='.5'/></svg>");
}
main,header.site-head,footer.site-foot{position:relative;z-index:1}

.skip-link{
  position:fixed;left:8px;top:-200px;z-index:40;
  background:var(--ink);color:var(--paper);padding:12px 20px;border-radius:0 0 8px 0;
  font-size:14px;text-decoration:none;transition:top .2s var(--ease);
}
.skip-link:focus{top:0}

:focus-visible{outline:3px solid var(--accent);outline-offset:3px;border-radius:4px}

/* ── 页头 ── */
.site-head{
  position:sticky;top:0;z-index:20;
  display:flex;align-items:center;gap:24px;
  padding:11px clamp(16px,4vw,64px);
  background:rgba(244,239,230,.9);
  backdrop-filter:blur(14px);
  border-bottom:1px solid var(--line-soft);
}
.brand{display:flex;align-items:baseline;gap:9px;text-decoration:none;flex:none}
.brand-cn{font-family:var(--f-serif);font-size:22px;letter-spacing:.06em;font-weight:600}
.brand-latin{font-family:var(--f-mono);font-size:11px;letter-spacing:.24em;color:var(--ink-muted)}
.site-nav{display:flex;gap:4px;margin-left:auto}
.site-nav a{
  text-decoration:none;font-size:14px;color:var(--ink-2);
  padding:10px 13px;border-radius:6px;transition:background .28s var(--ease),color .28s var(--ease);
}
.site-nav a:hover{background:rgba(23,51,0,.06);color:var(--ink)}
.head-cta{
  flex:none;text-decoration:none;font-size:14px;font-weight:500;
  background:var(--ink);color:#F6F1E6;padding:11px 20px;border-radius:4px;
  transition:transform .3s var(--ease),background .3s var(--ease);
}
.head-cta:hover{background:#26460D;transform:translateY(-1px)}
.head-cta:active{transform:translateY(0)}

/* ── 首屏 ── */
.hero{padding:0 0 clamp(40px,6vw,72px)}
.hero-figure{position:relative;overflow:hidden}
.mountain{width:100%;height:clamp(400px,58vw,620px)}

.hero-copy{
  position:absolute;left:clamp(20px,7vw,120px);top:13%;max-width:min(560px,80%);
  animation:rise 1s var(--ease) both;
}
@keyframes rise{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:none}}
.eyebrow{
  font-family:var(--f-mono);font-size:12px;letter-spacing:.2em;
  color:var(--brown);
  border-left:2px solid var(--accent);padding-left:10px;margin-bottom:20px;
}
.hero-copy h1{font-family:var(--f-serif);font-weight:600;line-height:1.06}
.hero-copy .l1{display:block;font-size:clamp(46px,7.2vw,88px);letter-spacing:.1em}
.hero-copy .l2{
  display:block;font-size:clamp(21px,2.6vw,32px);letter-spacing:.16em;
  color:var(--ink-2);margin-top:12px;
}
.hero-lede{
  margin-top:22px;max-width:26em;font-size:16px;line-height:1.72;color:var(--ink-2);
}
.hero-actions{display:flex;align-items:center;gap:12px;margin-top:30px;flex-wrap:wrap}

.btn-primary{
  font-family:var(--f-sans);font-size:15px;font-weight:500;
  background:var(--ink);color:#F7F2E8;border:none;cursor:pointer;
  padding:14px 30px;border-radius:4px;text-decoration:none;display:inline-block;
  min-height:48px;line-height:20px;
  box-shadow:var(--shadow-lift);
  transition:transform .32s var(--ease),background .32s var(--ease),box-shadow .32s var(--ease);
}
.btn-primary:hover{background:#26460D;transform:translateY(-2px)}
.btn-primary:active{transform:translateY(0) scale(.985)}
.btn-primary[disabled]{background:#B9B3A4;color:#EEEAE1;cursor:not-allowed;box-shadow:none;transform:none}

/* 次级链接：自带纸底衬垫，确保压在任何雾层上仍可读 */
.link-quiet{
  font-size:14px;color:var(--ink-2);text-decoration:none;
  padding:11px 16px;min-height:44px;display:inline-flex;align-items:center;
  background:rgba(244,239,230,.92);border-radius:4px;
  border-bottom:1px solid var(--ink-2);
  transition:color .3s var(--ease),border-color .3s var(--ease),background .3s var(--ease);
}
.link-quiet:hover{color:var(--accent);border-color:var(--accent);background:#F7F3EA}

.hero-specs{
  position:absolute;right:clamp(20px,6vw,110px);bottom:34px;
  display:flex;gap:clamp(20px,3vw,44px);margin:0;
  background:rgba(244,239,230,.94);backdrop-filter:blur(10px);
  border:1px solid var(--line-soft);border-radius:6px;
  padding:14px 22px;
  box-shadow:0 12px 30px -18px rgba(23,51,0,.4);
}
.hero-specs dt{font-family:var(--f-mono);font-size:11px;letter-spacing:.14em;color:var(--ink-muted)}
.hero-specs dd{margin:3px 0 0;font-size:14px;font-weight:500;color:var(--ink)}

/* ── 通用区块 ── */
.section{padding:clamp(64px,9vw,132px) clamp(20px,7vw,120px)}
.section-rooms{background:var(--paper-deep)}
.sec-head{display:flex;gap:clamp(18px,3vw,40px);align-items:flex-start;margin-bottom:clamp(36px,5vw,64px)}
.sec-index{
  font-family:var(--f-mono);font-size:12px;letter-spacing:.08em;color:var(--accent);
  padding-top:12px;flex:none;
}
.sec-head h2{
  font-family:var(--f-serif);font-weight:600;
  font-size:clamp(27px,3.9vw,46px);line-height:1.2;letter-spacing:.02em;
  max-width:22em;
}

/* ── 故事 7:3 ── */
.story-grid{display:grid;grid-template-columns:7fr 3fr;gap:clamp(32px,6vw,88px);align-items:start}
.story-body p{font-size:16.5px;line-height:1.82;color:var(--ink-2);max-width:34em;margin-bottom:22px}
.story-body strong{color:var(--ink);font-weight:600;border-bottom:2px solid var(--accent);padding-bottom:1px}
.story-note{
  border-top:1px solid var(--line);border-bottom:1px solid var(--line);
  padding:20px 0;font-size:15px;color:var(--ink-muted);
  font-family:var(--f-serif);margin-top:32px !important;
}
.story-side{border-left:1px solid var(--line);padding-left:clamp(20px,3vw,36px)}
.story-side h3{font-size:15px;font-weight:600;letter-spacing:.06em;color:var(--ink);margin-bottom:20px}
.bare-list{list-style:none;margin:0;padding:0}
.bare-list li{
  display:flex;gap:10px;font-size:14.5px;color:var(--ink-2);
  padding:13px 0;border-bottom:1px solid var(--line-soft);line-height:1.5;
}
.mk{color:var(--accent);font-family:var(--f-mono);flex:none}
.side-foot{font-size:13.5px;color:var(--ink-muted);margin-top:22px;line-height:1.6}

/* ── 房型 ── */
.room-tabs{display:flex;gap:8px;margin-bottom:clamp(28px,4vw,48px);flex-wrap:wrap}
.room-tab{
  display:flex;flex-direction:column;gap:3px;align-items:flex-start;
  background:transparent;border:1px solid var(--line);border-radius:6px;
  padding:14px 26px;cursor:pointer;min-height:64px;min-width:152px;
  font-family:var(--f-sans);text-align:left;
  transition:border-color .32s var(--ease),background .32s var(--ease),transform .32s var(--ease);
}
.room-tab:hover{border-color:var(--ink-2);transform:translateY(-2px)}
.room-tab.is-on{background:var(--ink);border-color:var(--ink)}
.tab-cn{font-family:var(--f-serif);font-size:19px;font-weight:600;color:var(--ink);transition:color .3s var(--ease)}
.room-tab.is-on .tab-cn{color:#F7F2E8}
.tab-meta{font-family:var(--f-mono);font-size:11px;letter-spacing:.1em;color:var(--ink-muted);transition:color .3s var(--ease)}
.room-tab.is-on .tab-meta{color:#B7C4A4}

.room-stage{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(28px,5vw,72px);align-items:start}
.room-figure{margin:0;position:sticky;top:88px}
.room-scene{
  width:100%;border-radius:6px;background:#EFE7D6;
  border:1px solid var(--line-soft);box-shadow:var(--shadow-lift);
}
#viewYun,#viewSong,#mullion,#mullion2,#mullion2b{transition:opacity .5s var(--ease)}
.fig-cap{
  font-family:var(--f-mono);font-size:12.5px;letter-spacing:.06em;
  color:var(--ink-muted);margin-top:14px;
}

.room-panel h3{font-family:var(--f-serif);font-size:clamp(26px,2.6vw,34px);letter-spacing:.08em;margin-bottom:8px}
.room-kicker{font-size:15px;color:var(--accent);margin-bottom:20px;letter-spacing:.02em}
.room-desc{font-size:16px;line-height:1.78;color:var(--ink-2);max-width:33em;margin-bottom:30px}
.room-facts{
  display:grid;grid-template-columns:1fr 1fr;gap:0;margin:0 0 30px;
  border-top:1px solid var(--line);
}
.room-facts > div{padding:15px 0;border-bottom:1px solid var(--line-soft)}
.room-facts dt{font-family:var(--f-mono);font-size:11px;letter-spacing:.12em;color:var(--ink-muted);margin-bottom:4px}
.room-facts dd{margin:0;font-size:15px;font-weight:500;color:var(--ink)}
.amen-title{font-size:14px;font-weight:600;letter-spacing:.08em;margin-bottom:14px}
.amen{list-style:none;margin:0;padding:0}
.amen li{
  font-size:15px;color:var(--ink-2);padding:11px 0 11px 22px;position:relative;
  border-bottom:1px dashed var(--line);line-height:1.5;
}
.amen li::before{
  content:"";position:absolute;left:2px;top:19px;
  width:7px;height:7px;border:1px solid var(--accent);transform:rotate(45deg);
}
.room-note{font-size:13.5px;color:var(--ink-muted);margin-top:26px;line-height:1.6}
.room-panel{outline-offset:8px}
.room-panel.fade{animation:fadeSwap .5s var(--ease) both}
@keyframes fadeSwap{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}

/* ── 日程 ── */
.day-lede{font-size:16.5px;line-height:1.78;color:var(--ink-2);max-width:34em;margin:-16px 0 clamp(36px,5vw,60px) 0}
.day-lede strong{color:var(--ink)}
.timeline{list-style:none;margin:0;padding:0;border-top:1px solid var(--line)}
.timeline li{
  display:grid;grid-template-columns:minmax(90px,148px) 1fr;
  gap:clamp(16px,4vw,56px);padding:clamp(22px,3vw,34px) 0;
  border-bottom:1px solid var(--line-soft);
  transition:background .4s var(--ease);
}
.timeline li:hover{background:rgba(23,51,0,.028)}
.tl-time{font-family:var(--f-mono);font-size:14px;letter-spacing:.06em;color:var(--accent);padding-top:3px}
.tl-body h3{font-family:var(--f-serif);font-size:19px;font-weight:600;letter-spacing:.03em;margin-bottom:8px}
.tl-body p{font-size:15.5px;line-height:1.72;color:var(--ink-2);max-width:38em}

/* ── 到访准备 ── */
.section-prepare{background:var(--paper-deep)}
.prep-grid{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(0,1fr);gap:clamp(32px,6vw,80px);align-items:start}
.prep-item{border-bottom:1px solid var(--line)}
.prep-item:first-child{border-top:1px solid var(--line)}
.prep-item summary{
  cursor:pointer;list-style:none;padding:20px 40px 20px 0;position:relative;
  font-size:17px;font-weight:500;color:var(--ink);letter-spacing:.03em;
  min-height:64px;display:flex;align-items:center;
}
.prep-item summary::-webkit-details-marker{display:none}
.prep-item summary::after{
  content:"";position:absolute;right:6px;top:50%;
  width:12px;height:12px;margin-top:-6px;
  border-right:1.5px solid var(--ink-2);border-bottom:1.5px solid var(--ink-2);
  transform:rotate(45deg);transition:transform .34s var(--ease);
}
.prep-item[open] summary::after{transform:rotate(-135deg)}
.prep-item summary:hover{color:var(--accent)}
.prep-body{padding:0 0 24px;max-width:36em;animation:fadeSwap .4s var(--ease) both}
.prep-body p{font-size:15.5px;line-height:1.78;color:var(--ink-2);margin-bottom:12px}
.prep-warn{
  border-left:2px solid var(--accent);padding-left:14px;color:var(--brown) !important;
  font-size:14.5px !important;
}
.prep-side{padding-left:clamp(0px,3vw,36px);border-left:1px solid var(--line)}
.prep-side h3{font-size:15px;font-weight:600;letter-spacing:.06em;margin-bottom:24px}
.side-fact{padding:18px 0;border-bottom:1px solid var(--line-soft)}
.side-fact:first-of-type{border-top:1px solid var(--line-soft)}
.sf-num{
  font-family:var(--f-serif);font-size:42px;font-weight:600;color:var(--ink);
  line-height:1;letter-spacing:.01em;
}
.sf-num span{font-family:var(--f-sans);font-size:14px;color:var(--ink-muted);margin-left:6px;letter-spacing:0}
.sf-lab{font-size:14px;color:var(--ink-2);margin-top:8px}

/* ── 行程意向 ── */
.plan-lede{font-size:16.5px;line-height:1.78;color:var(--ink-2);max-width:34em;margin:-16px 0 clamp(36px,5vw,56px) 0}
.plan-lede strong{color:var(--ink)}
.plan-grid{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr);gap:clamp(28px,5vw,64px);align-items:start}

.plan-form{
  background:var(--panel);border:1px solid var(--line);border-radius:6px;
  padding:clamp(24px,3vw,40px);box-shadow:var(--shadow-lift);
}
.field{margin-bottom:24px;border:none;padding:0}
.field > label,.field > legend{
  display:block;font-size:14px;font-weight:600;color:var(--ink);
  margin-bottom:9px;letter-spacing:.04em;
}
.field input[type="date"],.field textarea{
  width:100%;font-family:var(--f-sans);font-size:15px;color:var(--ink);
  background:#FFFDF8;border:1px solid var(--line);border-radius:4px;
  padding:13px 14px;min-height:48px;
  transition:border-color .28s var(--ease),box-shadow .28s var(--ease);
}
.field textarea{resize:vertical;line-height:1.6}
.field input[type="date"]:hover,.field textarea:hover{border-color:var(--ink-2)}
.field input[type="date"]:focus,.field textarea:focus{
  outline:none;border-color:var(--ink);box-shadow:0 0 0 3px rgba(169,97,31,.22);
}
.field input[aria-invalid="true"]{border-color:#A33A1E;background:#FDF4EF}

.radio-row{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.radio-card{
  display:flex;align-items:center;gap:11px;cursor:pointer;
  border:1px solid var(--line);border-radius:4px;background:#FFFDF8;
  padding:14px;min-height:64px;
  transition:border-color .3s var(--ease),background .3s var(--ease),transform .3s var(--ease);
}
.radio-card:hover{border-color:var(--ink-2);transform:translateY(-2px)}
.radio-card input{accent-color:var(--ink);width:17px;height:17px;flex:none;margin:0}
.radio-card:has(input:checked){border-color:var(--ink);background:#F1EEE3;box-shadow:inset 0 0 0 1px var(--ink)}
.rc-body{display:flex;flex-direction:column;gap:3px}
.rc-name{font-family:var(--f-serif);font-size:16px;font-weight:600;letter-spacing:.06em}
.rc-meta{font-family:var(--f-mono);font-size:11px;letter-spacing:.06em;color:var(--ink-muted)}

.form-error{
  display:flex;flex-direction:column;gap:4px;font-size:14px;line-height:1.55;
  background:#FBF0E6;border:1px solid #D8A87C;border-left:3px solid #A33A1E;
  color:#7A2E11;border-radius:4px;padding:13px 15px;margin:0 0 20px;
  animation:fadeSwap .34s var(--ease) both;
}
.form-error strong{font-weight:600}
.form-error[hidden]{display:none}
.form-actions{display:flex;gap:14px;align-items:center;flex-wrap:wrap;margin-top:4px}
.btn-ghost{
  font-family:var(--f-sans);font-size:14.5px;color:var(--ink);
  background:transparent;border:1px solid var(--line);border-radius:4px;
  padding:13px 24px;min-height:48px;cursor:pointer;
  transition:border-color .3s var(--ease),background .3s var(--ease);
}
.btn-ghost:hover{border-color:var(--ink);background:rgba(23,51,0,.05)}
.btn-quiet{
  font-family:var(--f-sans);font-size:14px;color:var(--accent);
  background:none;border:none;border-bottom:1px solid var(--accent);
  padding:10px 2px;min-height:44px;cursor:pointer;
}
.btn-quiet:hover{color:var(--ink);border-color:var(--ink)}
.form-legal{font-size:13px;color:var(--ink-muted);margin-top:18px;line-height:1.6}

.plan-out{
  background:var(--ink);color:#EDE7D9;border-radius:6px;
  padding:clamp(24px,3vw,40px);position:sticky;top:88px;
}
.plan-out h3{
  font-family:var(--f-serif);font-size:20px;font-weight:600;letter-spacing:.08em;
  color:#F4EFE6;margin-bottom:22px;
}
.out-empty{border-top:1px solid rgba(244,239,230,.2);padding-top:24px}
.oe-line{font-family:var(--f-serif);font-size:19px;line-height:1.6;color:#DCD4C2;letter-spacing:.03em}
.oe-sub{font-size:14px;color:#A8B098;margin:12px 0 20px;line-height:1.6}
.out-list{margin:0;border-top:1px solid rgba(244,239,230,.22)}
.out-list > div{
  display:flex;justify-content:space-between;gap:16px;align-items:baseline;
  padding:14px 0;border-bottom:1px solid rgba(244,239,230,.14);
}
.out-list dt{font-family:var(--f-mono);font-size:11px;letter-spacing:.12em;color:#A0AA92;flex:none}
.out-list dd{margin:0;font-size:15.5px;color:#F4EFE6;text-align:right;font-weight:500}
.out-note{
  font-size:14px;line-height:1.7;color:#C3CBB2;margin-top:20px;
  border-left:2px solid var(--accent-warm);padding-left:14px;
}
.out-actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-top:26px}
.plan-out .btn-ghost{color:#EDE7D9;border-color:rgba(244,239,230,.32)}
.plan-out .btn-ghost:hover{border-color:#EDE7D9;background:rgba(244,239,230,.1)}
.plan-out .btn-quiet{color:var(--accent-warm);border-color:rgba(233,180,115,.55)}
.plan-out .btn-quiet:hover{color:#F4EFE6;border-color:#F4EFE6}
.copy-status{font-size:13px;color:#A8B098;margin-top:14px;min-height:18px}

/* ── 页脚 ── */
.site-foot{
  padding:clamp(44px,6vw,84px) clamp(20px,7vw,120px) clamp(32px,4vw,56px);
  border-top:1px solid var(--line);display:grid;
  grid-template-columns:auto 1fr auto;gap:clamp(20px,4vw,56px);align-items:start;
}
.fb-cn{font-family:var(--f-serif);font-size:30px;letter-spacing:.14em;font-weight:600}
.fb-latin{font-family:var(--f-mono);font-size:11px;letter-spacing:.3em;color:var(--ink-muted);margin-top:4px}
.foot-note{font-size:13.5px;line-height:1.75;color:var(--ink-muted);max-width:52em}
.foot-note strong{color:var(--ink-2)}
.foot-meta{font-family:var(--f-mono);font-size:11.5px;letter-spacing:.1em;color:var(--ink-muted);white-space:nowrap}

/* ── 修改提示：底部原位轻条 ── */
.dlg{
  position:fixed;left:0;right:0;bottom:0;z-index:30;
  padding:16px clamp(16px,4vw,40px);
  display:flex;justify-content:center;
  animation:rise .42s var(--ease) both;
}
.dlg[hidden]{display:none}
.dlg-panel{
  background:var(--panel);border:1px solid var(--line);border-radius:6px;
  box-shadow:0 -8px 40px -12px rgba(23,51,0,.28);
  padding:20px 24px;max-width:640px;width:100%;
  display:flex;gap:20px;align-items:center;flex-wrap:wrap;
}
.dlg-panel h3{font-size:16px;font-weight:600;margin-bottom:4px}
.dlg-panel p{font-size:14px;color:var(--ink-2);line-height:1.6;flex:1 1 260px}
.dlg-panel .btn-primary{padding:12px 22px;min-height:44px;font-size:14px;flex:none}

/* ── 响应式 ── */
@media (max-width:1080px){
  .story-grid,.prep-grid,.plan-grid{grid-template-columns:1fr}
  .story-side,.prep-side{border-left:none;padding-left:0;border-top:1px solid var(--line);padding-top:28px}
  .room-figure{position:static}
  .plan-out{position:static}
  .site-foot{grid-template-columns:1fr;gap:24px}
  .foot-meta{white-space:normal}
}
@media (max-width:900px){
  .room-stage{grid-template-columns:1fr}
}
@media (max-width:820px){
  .site-nav{display:none}
  .hero{padding-top:8px}
  .hero-copy{position:static;padding:0 clamp(20px,7vw,120px);max-width:none;margin-top:28px}
  .mountain{height:clamp(280px,64vw,380px)}
  .hero-specs{
    position:static;margin:24px clamp(20px,7vw,120px) 0;
    flex-wrap:wrap;gap:18px 28px;
  }
}
@media (max-width:600px){
  .room-tabs{gap:8px}
  .room-tab{flex:1 1 auto;min-width:0;padding:14px 18px}
  .radio-row{grid-template-columns:1fr}
  .room-facts{grid-template-columns:1fr}
  .timeline li{grid-template-columns:1fr;gap:8px}
  .tl-time{padding-top:0}
  .head-cta{padding:12px 16px}
}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{animation-duration:.01ms !important;transition-duration:.01ms !important}
  html{scroll-behavior:auto}
}

