/* 栖迟 QICHI —— 交互层
   1) 房型切换：联动窗洞图形 / 转角竖框 / 设施清单 / 图注（平滑流变，非直接换图）
   2) 日期约束与校验：离店必须晚于入住，错误出现在表单旁
   3) 本地行程意向摘要：仅在内存中生成，不上传、不写入 localStorage
*/
(function () {
  'use strict';

  var MS_DAY = 86400000;

  /* ─────────────── 工具 ─────────────── */
  function pad(n) { return n < 10 ? '0' + n : String(n); }
  function toISO(d) { return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()); }
  function addDays(iso, n) {
    var p = iso.split('-');
    var d = new Date(Number(p[0]), Number(p[1]) - 1, Number(p[2]));
    d.setDate(d.getDate() + n);
    return toISO(d);
  }
  function todayISO() {
    var d = new Date();
    return toISO(new Date(d.getFullYear(), d.getMonth(), d.getDate()));
  }
  function pretty(iso) {
    if (!iso) { return '—'; }
    var p = iso.split('-');
    return Number(p[1]) + ' 月 ' + Number(p[2]) + ' 日';
  }
  function nights(a, b) {
    if (!a || !b) { return 0; }
    return Math.round((new Date(b) - new Date(a)) / MS_DAY);
  }

  /* ─────────────── 1. 房型切换 ─────────────── */
  var roomData = {
    yun: {
      cap: '望云 · 谷侧宽窗，视线正对谷底雾带',
      headTitle: '望云 · 谷侧宽窗示意',
      desc: '随所选房型变化的窗洞示意：望云为谷侧宽窗，正对谷底雾带；听松为林侧转角窗，两面开窗外接松林近景。',
      corner: false
    },
    song: {
      cap: '听松 · 林侧转角窗，两面被松林包围',
      headTitle: '听松 · 林侧转角窗示意',
      desc: '随所选房型变化的窗洞示意：听松为林侧转角窗，西北两面开窗，窗外为松林近景。',
      corner: true
    }
  };

  var tabs = Array.prototype.slice.call(document.querySelectorAll('.room-tab'));
  var panels = Array.prototype.slice.call(document.querySelectorAll('.room-panel'));
  var viewYun = document.getElementById('viewYun');
  var viewSong = document.getElementById('viewSong');
  var figCap = document.getElementById('figCap');
  var rmTitle = document.getElementById('rm-title');
  var rmDesc = document.getElementById('rm-desc');
  var mullion2 = document.getElementById('mullion2');
  var mullion2b = document.getElementById('mullion2b');
  var planOut = document.getElementById('planOut');

  function selectRoom(key, focusTab) {
    var data = roomData[key];
    if (!data || !viewYun || !viewSong) { return; }

    tabs.forEach(function (tab) {
      var on = tab.getAttribute('data-room') === key;
      tab.classList.toggle('is-on', on);
      tab.setAttribute('aria-selected', on ? 'true' : 'false');
      tab.tabIndex = on ? 0 : -1;
      if (on && focusTab) { tab.focus(); }
    });

    panels.forEach(function (panel) {
      var on = panel.id === 'panel-' + key;
      panel.hidden = !on;
      if (on) {
        panel.classList.remove('fade');
        void panel.offsetWidth; /* 触发重排以重播切换动效 */
        panel.classList.add('fade');
      }
    });

    /* 图形联动：窗外景别 + 转角窗竖框 */
    viewYun.hidden = (key !== 'yun');
    viewSong.hidden = (key !== 'song');
    if (mullion2) { mullion2.setAttribute('opacity', data.corner ? '1' : '0'); }
    if (mullion2b) { mullion2b.setAttribute('opacity', data.corner ? '1' : '0'); }

    if (figCap) { figCap.textContent = data.cap; }
    if (rmTitle) { rmTitle.textContent = data.headTitle; }
    if (rmDesc) { rmDesc.textContent = data.desc; }

    /* 表单房型同步，减少重复输入 */
    var pick = document.getElementById(key === 'yun' ? 'pickYun' : 'pickSong');
    if (pick) { pick.checked = true; }
  }

  tabs.forEach(function (tab) {
    tab.addEventListener('click', function () {
      selectRoom(tab.getAttribute('data-room'), false);
    });
    tab.addEventListener('keydown', function (e) {
      var i = tabs.indexOf(tab);
      var next = null;
      if (e.key === 'ArrowRight' || e.key === 'ArrowDown') { next = tabs[(i + 1) % tabs.length]; }
      if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') { next = tabs[(i - 1 + tabs.length) % tabs.length]; }
      if (e.key === 'Home') { next = tabs[0]; }
      if (e.key === 'End') { next = tabs[tabs.length - 1]; }
      if (next) {
        e.preventDefault();
        selectRoom(next.getAttribute('data-room'), true);
      }
    });
  });

  /* ─────────────── 2. 日期 ─────────────── */
  var inDate = document.getElementById('inDate');
  var outDate = document.getElementById('outDate');
  var form = document.getElementById('planForm');
  var formError = document.getElementById('formError');
  var note = document.getElementById('planNote');

  function applyMinDates() {
    var t = todayISO();
    inDate.min = t;
    if (!inDate.value || inDate.value < t) { inDate.value = t; }
    outDate.min = addDays(inDate.value, 1);
    if (outDate.value && outDate.value <= inDate.value) {
      outDate.value = addDays(inDate.value, 1);
    }
  }

  function makeStayError() {
    return '离店日期需要晚于入住日期。现在两个日子相同或颠倒，请把离店改到 '
      + pretty(addDays(inDate.value, 1)) + ' 或之后。';
  }

  function showError(msg) {
    formError.innerHTML = '';
    var b = document.createElement('strong');
    b.textContent = '日期还不能成立';
    var s = document.createElement('span');
    s.textContent = msg;
    formError.appendChild(b);
    formError.appendChild(s);
    formError.hidden = false;
    outDate.setAttribute('aria-invalid', 'true');
  }

  function clearError() {
    formError.hidden = true;
    formError.textContent = '';
    outDate.removeAttribute('aria-invalid');
  }

  inDate.addEventListener('change', function () {
    var before = outDate.value;
    applyMinDates();
    if (before && before !== outDate.value) {
      showError('离店日期已自动顺延到 ' + pretty(outDate.value) + '，因为山居至少需要住一晚。');
      outDate.removeAttribute('aria-invalid');
    } else {
      clearError();
    }
  });

  outDate.addEventListener('change', function () {
    if (nights(inDate.value, outDate.value) <= 0) {
      showError(makeStayError());
    } else {
      clearError();
    }
  });

  /* ─────────────── 3. 行程意向 ─────────────── */
  var outEmpty = document.getElementById('outEmpty');
  var outFilled = document.getElementById('outFilled');
  var outList = document.getElementById('outList');
  var outNote = document.getElementById('outNote');
  var copyStatus = document.getElementById('copyStatus');
  var copyBtn = document.getElementById('copyBtn');

  function pickedRoom() {
    var el = form.querySelector('input[name="roomPick"]:checked');
    return el ? el.value : '望云';
  }

  function buildRows() {
    var room = pickedRoom();
    var n = nights(inDate.value, outDate.value);
    var rows = [
      ['入住', pretty(inDate.value) + '（' + inDate.value + '）'],
      ['离店', pretty(outDate.value) + '（' + outDate.value + '）'],
      ['停留', n + ' 晚'],
      ['房型意向', room + (room === '望云' ? ' · 谷侧宽窗' : ' · 林侧转角窗')],
      ['同行', '2 位成人']
    ];
    if (note.value.trim()) {
      rows.push(['想说的事', note.value.trim()]);
    }
    return rows;
  }

  function renderIntent() {
    outList.innerHTML = '';
    buildRows().forEach(function (row) {
      var wrap = document.createElement('div');
      var dt = document.createElement('dt');
      dt.textContent = row[0];
      var dd = document.createElement('dd');
      dd.textContent = row[1];
      wrap.appendChild(dt);
      wrap.appendChild(dd);
      outList.appendChild(wrap);
    });

    var wd = new Date(inDate.value).getDay();
    var isWeekend = (wd === 5 || wd === 6);

    outNote.textContent = '这是一段留在本页的行程意向，没有提交到任何服务器，也不代表房间已被保留。'
      + (isWeekend ? '你选的是周末，山里这时通常最安静，也最需要提前通信。' : '工作日上山的人少，屋后的溪声会更清楚。');

    outEmpty.hidden = true;
    outFilled.hidden = false;
    copyStatus.textContent = '';
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    if (!inDate.value) {
      showError('请先选择入住日期。最早可选的日期是 ' + pretty(todayISO()) + '。');
      inDate.focus();
      return;
    }
    if (!outDate.value) {
      showError('请选择离店日期。住一晚的话，建议选 ' + pretty(addDays(inDate.value, 1)) + '。');
      outDate.focus();
      return;
    }
    if (nights(inDate.value, outDate.value) <= 0) {
      showError(makeStayError());
      outDate.focus();
      return;
    }
    clearError();
    renderIntent();
    planOut.scrollIntoView({ block: 'nearest' });
  });

  form.addEventListener('reset', function () {
    window.setTimeout(function () {
      outList.innerHTML = '';
      outFilled.hidden = true;
      outEmpty.hidden = false;
      copyStatus.textContent = '';
      clearError();
      applyMinDates();
    }, 0);
  });

  var fillDemo = document.getElementById('fillDemo');
  if (fillDemo) {
    fillDemo.addEventListener('click', function () {
      var start = addDays(todayISO(), 12);
      var d = new Date(start);
      while (d.getDay() !== 5) { d.setDate(d.getDate() + 1); }
      start = toISO(d);
      inDate.value = start;
      outDate.value = addDays(start, 2);
      applyMinDates();
      clearError();
      renderIntent();
      planOut.scrollIntoView({ block: 'nearest' });
    });
  }

  if (copyBtn) {
    copyBtn.addEventListener('click', function () {
      var text = '栖迟 QICHI · 行程意向（概念示例，未提交）\n'
        + buildRows().map(function (r) { return r[0] + '：' + r[1]; }).join('\n');
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(function () {
          copyStatus.textContent = '已复制。可以直接粘贴到邮件或消息里发给我们。';
        }, function () {
          copyStatus.textContent = '浏览器没有允许复制，请手动选中上面的内容。';
        });
      } else {
        copyStatus.textContent = '这个浏览器不支持自动复制，请手动选中上面的内容。';
      }
    });
  }

  /* 修改提示：底部原位轻条，不用遮罩大弹窗 */
  var editBtn = document.getElementById('editBtn');
  var editDlg = document.getElementById('editDlg');
  var dlgClose = document.getElementById('dlgClose');
  if (editBtn && editDlg) {
    editBtn.addEventListener('click', function () { editDlg.hidden = false; });
  }
  if (dlgClose && editDlg) {
    dlgClose.addEventListener('click', function () {
      editDlg.hidden = true;
      inDate.focus();
    });
  }

  /* ─────────────── 初始化 ─────────────── */
  applyMinDates();
  selectRoom('yun', false);
})();
